{
  "ok": false,
  "name": "find_entities",
  "error": {
    "type": "query_failed",
    "message": "visible_on filters model entities by what a sheet shows",
    "hint": "drop space (it defaults to model), or drop visible_on to list a sheet's own entities"
  }
}

[tool error]
{
  "ok": false,
  "name": "draw_line",
  "error": {
    "type": "command_failed",
    "message": "layer 'V-LAYOUT-MATCH' does not exist",
    "hint": "existing layers: ['0', 'align_CURVE-DATA', 'border_INSIDE-BORDER-anno', 'pp_LEGEND-anno', 'pp_PRESENTATION', 'rd_LAYOUT-NOTE-anno']; create it with create_layer",
    "example": {
      "space": "model",
      "start": [
        4100.0,
        7300.0
      ],
      "end": [
        4700.0,
        7300.0
      ],
      "layer": "V-ALIGN-CNTR"
    }
  },
  "warnings": []
}

[tool error]
{
  "ok": false,
  "name": "create_layer",
  "error": {
    "type": "invalid_params",
    "message": "'name' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        },
        "lineweight_mm": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "plotted lineweight in mm"
        },
        "description": {
          "type": "string"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
    "example": {
      "name": "align_MAIN",
      "color": "black",
      "linetype": "continuous",
      "lineweight_mm": 0.35,
      "description": "Roadway centerline"
    }
  },
  "warnings": []
}

